'use client'

import {
  type CSSProperties,
  type ReactNode,
  useEffect,
  useRef,
  useState,
  useSyncExternalStore,
} from 'react'
import { APSViewerContext } from '@/components/ui/aps-viewer/context'
import {
  acquireViewerRuntime,
  onViewerTokenError,
  releaseViewerRuntime,
  toDocumentId,
} from '@/components/ui/aps-viewer/loader'
import { ViewerStore } from '@/components/ui/aps-viewer/store'
import {
  APS_VIEWER_TOOLBAR_EXTENSION_ID,
  type APSViewerToolbarExtension,
  type APSViewerToolbarPosition,
  type APSViewerToolbarScale,
  registerAPSViewerToolbar,
} from '@/components/ui/aps-viewer/toolbar'
import type {
  APSDocument,
  APSExtensionRequest,
  APSModel,
  APSViewer3D,
  APSViewerProfile,
  GetAccessToken,
} from '@/lib/viewer-types'

export type {
  APSViewerToolbarPosition,
  APSViewerToolbarScale,
} from '@/components/ui/aps-viewer/toolbar'

export interface APSViewerProps {
  /**
   * Model Derivative URN (base64), with or without the `urn:` prefix.
   * Omit to mount an empty viewer and load models imperatively via
   * `onViewerReady` / `useAPSViewer`.
   */
  urn?: string
  /** Fetches an OAuth token from your backend. Must be referentially stable
   * or the value at first mount wins (the SDK initializer is global). */
  getAccessToken: GetAccessToken
  /** SDK version (default '7.*') */
  version?: string
  /** Initializer env (default 'AutodeskProduction2') */
  env?: string
  /** Initializer api (default 'streamingV2') */
  api?: string
  /**
   * Extensions to load once the viewer starts: bare ids, or `{ id, options }`
   * entries when the extension reads load options. Captured when the viewer
   * mounts. Load progress is observable via `useAPSExtensions()`; failures
   * report through `onExtensionError`. The `viewer-extension-types` item
   * catalogs the public ids and types their options.
   */
  extensions?: readonly APSExtensionRequest[]
  /** Extra config passed to the GuiViewer3D constructor */
  viewerConfig?: Record<string, unknown>
  /**
   * Named Autodesk settings profile applied at creation — `'aec'` is
   * Autodesk's "Construction (AEC)" tuning (reversed zoom, edge rendering,
   * AEC light preset). Omit for the SDK default.
   */
  profile?: APSViewerProfile
  /** Native GuiViewer3D toolbar, or the toolbar-less core Viewer3D. */
  toolbar?: 'native' | 'none'
  /** Edge where the native toolbar docks. Changes apply live. */
  toolbarPosition?: APSViewerToolbarPosition
  /** Native toolbar button-box size. `md` is the 44px default. Changes apply live. */
  toolbarScale?: APSViewerToolbarScale
  /** Show Autodesk's ViewCube and its companion controls. Default true. */
  viewCube?: boolean
  /** Clip the viewer frame to this pixel radius, clamped to 0–32. */
  radius?: number
  /** Force one appearance. Omit to follow the app's light/dark appearance live. */
  theme?: 'light' | 'dark'
  /** Observe the viewer container and resize the WebGL canvas. Default true. */
  autoResize?: boolean
  /** Shut the whole SDK runtime down when the last viewer unmounts.
   * Default false: keeps the runtime warm across route changes. */
  shutdownOnUnmount?: boolean
  onViewerReady?: (viewer: APSViewer3D) => void
  onModelLoaded?: (model: APSModel, doc: APSDocument) => void
  onError?: (error: Error) => void
  /** An extension from `extensions` failed to load. Non-fatal: the viewer and
   * the other extensions keep going, so this is a report, not a teardown. */
  onExtensionError?: (id: string, error: Error) => void
  className?: string
  style?: CSSProperties
  /** Overlay UI. Rendered inside the provider, absolutely positioned children
   * can sit on top of the canvas and use every hook. */
  children?: ReactNode
}

/** A bare id and an `{ id, options }` entry are the same request. */
function toExtensionEntry(request: APSExtensionRequest): {
  id: string
  options?: Record<string, unknown>
} {
  return typeof request === 'string' ? { id: request } : request
}

/** Unloading is best-effort: the viewer may already be finished. */
function unloadModel(viewer: APSViewer3D | null, model: APSModel | null): void {
  if (!viewer || !model) return
  try {
    viewer.unloadModel(model)
  } catch {
    // the viewer is gone; the model went with it
  }
}

/** Disable ViewCube at construction so GuiViewer3D cannot auto-load it after
 * the live visibility effect has already asked it to unload. */
function withInitialViewCube(
  viewerConfig: Record<string, unknown> | undefined,
  viewCube: boolean,
): Record<string, unknown> | undefined {
  if (viewCube) return viewerConfig
  const configured = viewerConfig?.disabledExtensions
  const disabledExtensions =
    configured && typeof configured === 'object' ? configured : ({} as Record<string, unknown>)
  return {
    ...viewerConfig,
    disabledExtensions: { ...disabledExtensions, viewcube: true },
  }
}

/**
 * APS Viewer container. Renders a plain positioned <div> on the
 * server (SSR-safe: no window access until effects run), then on the client:
 *
 *  1. loads the SDK script/CSS from the Autodesk CDN exactly once,
 *  2. runs the global Initializer exactly once,
 *  3. instantiates a viewer bound to this component's lifetime,
 *  4. tears everything down on unmount — including under React Strict Mode's
 *     mount → unmount → remount cycle, which is where naive wrappers leak
 *     WebGL contexts.
 */
export function APSViewer({
  urn,
  getAccessToken,
  version,
  env,
  api,
  extensions,
  viewerConfig,
  profile,
  toolbar = 'native',
  toolbarPosition = 'bottom',
  toolbarScale = 'md',
  viewCube = true,
  radius,
  theme,
  autoResize = true,
  shutdownOnUnmount = false,
  onViewerReady,
  onModelLoaded,
  onError,
  onExtensionError,
  className,
  style,
  children,
}: APSViewerProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const [store] = useState(() => new ViewerStore())
  // Lifecycle status lives in the store: the viewer is an external imperative
  // resource, so its lifecycle is external state, not component state.
  const status = useSyncExternalStore(store.subscribe, store.getStatus, ViewerStore.getServerStatus)
  const [viewerEpoch, setViewerEpoch] = useState(0)
  const viewerRef = useRef<APSViewer3D | null>(null)
  const viewCubeRef = useRef(viewCube)
  const toolbarOptionsRef = useRef({ position: toolbarPosition, scale: toolbarScale })
  const frameRadius =
    radius === undefined || !Number.isFinite(radius) ? undefined : Math.min(32, Math.max(0, radius))

  // Latest-value refs so effect deps stay minimal and consumers can pass
  // inline closures and literals without recreating the viewer.
  // `shutdownOnUnmount` is only read at cleanup; `viewerConfig` and
  // `extensions` are captured when the viewer is created — listing any of
  // them as a dependency would tear down the WebGL context whenever a
  // consumer passes a fresh object or array literal.
  const callbacksRef = useRef({
    getAccessToken,
    onViewerReady,
    onModelLoaded,
    onError,
    onExtensionError,
    shutdownOnUnmount,
    viewerConfig,
    extensions,
  })
  // Synced after commit, not during render: a render React discards (Strict
  // Mode, a concurrent restart) must never leave its callbacks behind.
  useEffect(() => {
    callbacksRef.current = {
      getAccessToken,
      onViewerReady,
      onModelLoaded,
      onError,
      onExtensionError,
      shutdownOnUnmount,
      viewerConfig,
      extensions,
    }
  })

  useEffect(() => {
    viewCubeRef.current = viewCube
  }, [viewCube])

  useEffect(() => {
    toolbarOptionsRef.current = { position: toolbarPosition, scale: toolbarScale }
  }, [toolbarPosition, toolbarScale])

  useEffect(() => {
    const container = containerRef.current
    if (!container) return
    let disposed = false
    let viewer: APSViewer3D | null = null

    store.setStatus('loading-runtime')
    acquireViewerRuntime({
      getAccessToken: () => callbacksRef.current.getAccessToken(),
      version,
      env,
      api,
    })
      .then((autodesk) => {
        // Strict Mode: the first effect's cleanup may already have run.
        if (disposed) return
        const Ctor = toolbar === 'none' ? autodesk.Viewing.Viewer3D : autodesk.Viewing.GuiViewer3D
        viewer = new Ctor(
          container,
          withInitialViewCube(callbacksRef.current.viewerConfig, viewCubeRef.current),
        )
        const startCode = viewer.start()
        if (startCode > 0) {
          throw new Error(`cantera aps-viewer: viewer.start() failed with code ${startCode}`)
        }
        viewerRef.current = viewer
        store.attach(viewer)
        // Constructor-time options such as `toolbar` replace the Viewer
        // instance. Track that identity explicitly: the runtime can resolve so
        // quickly that `loading-runtime` → `ready` batches into the same status
        // value and would otherwise fail to restart model loading.
        setViewerEpoch((previous) => previous + 1)
        if (profile) {
          const settings = {
            aec: autodesk.Viewing.ProfileSettings.AEC,
            default: autodesk.Viewing.ProfileSettings.Default,
            fluent: autodesk.Viewing.ProfileSettings.Fluent,
            navis: autodesk.Viewing.ProfileSettings.Navis,
          }[profile]
          if (settings) viewer.setProfile(new autodesk.Viewing.Profile(settings))
        }
        const boundViewer = viewer
        if (toolbar === 'native') {
          registerAPSViewerToolbar(autodesk)
          boundViewer
            .loadExtension(APS_VIEWER_TOOLBAR_EXTENSION_ID, toolbarOptionsRef.current)
            .then((extension) => {
              if (disposed) {
                boundViewer.unloadExtension(APS_VIEWER_TOOLBAR_EXTENSION_ID)
                return
              }
              const nativeToolbar = extension as APSViewerToolbarExtension
              nativeToolbar.setOptions(toolbarOptionsRef.current)
            })
            .catch((error) => {
              if (disposed) return
              const wrapped =
                error instanceof Error
                  ? error
                  : new Error('cantera aps-viewer: native toolbar configuration failed')
              console.error('cantera aps-viewer: failed to configure the native toolbar', error)
              callbacksRef.current.onExtensionError?.(APS_VIEWER_TOOLBAR_EXTENSION_ID, wrapped)
            })
        }
        for (const request of callbacksRef.current.extensions ?? []) {
          const { id, options } = toExtensionEntry(request)
          store.setExtensionStatus(id, 'loading')
          boundViewer
            .loadExtension(id, options)
            .then(() => {
              if (!disposed) store.setExtensionStatus(id, 'ready')
            })
            .catch((error) => {
              if (disposed) return
              store.setExtensionStatus(id, 'error')
              const wrapped =
                error instanceof Error
                  ? error
                  : new Error(`cantera aps-viewer: failed to load extension "${id}"`)
              console.error(`cantera aps-viewer: failed to load extension "${id}"`, error)
              callbacksRef.current.onExtensionError?.(id, wrapped)
            })
        }
        store.setStatus('ready')
        callbacksRef.current.onViewerReady?.(viewer)
      })
      .catch((error: Error) => {
        if (disposed) return
        store.setStatus('error')
        callbacksRef.current.onError?.(error)
      })

    return () => {
      disposed = true
      // detach() also resets the store's status to 'idle'.
      store.detach()
      if (viewer) {
        viewer.unloadExtension(APS_VIEWER_TOOLBAR_EXTENSION_ID)
        viewer.finish()
        viewer = null
        viewerRef.current = null
      }
      releaseViewerRuntime({ shutdown: callbacksRef.current.shutdownOnUnmount })
    }
  }, [version, env, api, toolbar, profile, store])

  // Appearance is deliberately separate from viewer lifetime: a theme switch
  // calls setTheme in place and never burns a second WebGL context.
  useEffect(() => {
    if (status !== 'ready') return
    const viewer = viewerRef.current
    if (!viewer || typeof window === 'undefined') return

    const media = window.matchMedia('(prefers-color-scheme: dark)')
    const apply = () => {
      const root = document.documentElement
      const dark = theme
        ? theme === 'dark'
        : root.classList.contains('dark') || (!root.classList.contains('light') && media.matches)
      viewer.setTheme(dark ? 'dark-theme' : 'light-theme')
    }
    apply()
    if (theme) return

    const observer = new MutationObserver(apply)
    observer.observe(document.documentElement, { attributes: true, attributeFilter: ['class'] })
    media.addEventListener('change', apply)
    return () => {
      observer.disconnect()
      media.removeEventListener('change', apply)
    }
  }, [status, theme])

  // ViewCube APIs moved into Autodesk.ViewCubeUi in LMV v7. Treat it as live
  // chrome: load/unload the extension without replacing the WebGL viewer.
  useEffect(() => {
    if (viewerEpoch === 0 || status !== 'ready') return
    const viewer = viewerRef.current
    if (!viewer) return
    let cancelled = false
    const id = 'Autodesk.ViewCubeUi'

    if (viewCube) {
      viewer
        .loadExtension(id)
        .then(() => {
          if (cancelled && (!viewCubeRef.current || viewerRef.current !== viewer)) {
            viewer.unloadExtension(id)
          }
        })
        .catch((error) => {
          if (cancelled) return
          const wrapped =
            error instanceof Error
              ? error
              : new Error('cantera aps-viewer: ViewCube failed to load')
          console.error('cantera aps-viewer: failed to load the ViewCube extension', error)
          callbacksRef.current.onExtensionError?.(id, wrapped)
        })
    } else {
      viewer.unloadExtension(id)
    }

    return () => {
      cancelled = true
    }
  }, [status, viewCube, viewerEpoch])

  // The toolbar belongs to APSViewer: inspector controls update its docking
  // and touch-target scale without a child component or a WebGL restart.
  useEffect(() => {
    if (viewerEpoch === 0 || status !== 'ready' || toolbar !== 'native') return
    const extension = viewerRef.current?.getExtension(APS_VIEWER_TOOLBAR_EXTENSION_ID) as
      | APSViewerToolbarExtension
      | null
      | undefined
    extension?.setOptions({ position: toolbarPosition, scale: toolbarScale })
  }, [status, toolbar, toolbarPosition, toolbarScale, viewerEpoch])

  // The SDK's token callback cannot reject, so the loader broadcasts token
  // failures instead: without this the viewer would sit at "loading" forever
  // with nothing reported to the consumer.
  useEffect(
    () =>
      onViewerTokenError((error) => {
        // A ready viewer keeps rendering with its last good token; anything
        // earlier in the lifecycle cannot finish loading without one.
        if (store.getStatus() !== 'ready') store.setStatus('error')
        callbacksRef.current.onError?.(error)
      }),
    [store],
  )

  useEffect(() => {
    if (!autoResize || status !== 'ready' || typeof ResizeObserver === 'undefined') return
    const viewer = viewerRef.current
    if (!viewer) return
    const observer = new ResizeObserver(() => viewer.resize())
    observer.observe(viewer.container)
    return () => observer.disconnect()
  }, [autoResize, status])

  // Model loading is a separate concern from viewer lifetime: swapping `urn`
  // reuses the live viewer instead of recreating the WebGL context.
  useEffect(() => {
    const viewer = viewerRef.current
    const autodesk = typeof window !== 'undefined' ? window.Autodesk : undefined
    if (viewerEpoch === 0 || status !== 'ready' || !viewer || !autodesk) return
    if (!urn) return

    let cancelled = false
    let loadedModel: APSModel | null = null
    // A URN swap reuses this store, so the previous model's snapshot has to
    // go before the next document starts loading.
    store.resetModel()

    autodesk.Viewing.Document.load(
      toDocumentId(urn),
      (doc) => {
        if (cancelled) return
        const geometry = doc.getRoot().getDefaultGeometry()
        if (!geometry) {
          callbacksRef.current.onError?.(
            new Error('cantera aps-viewer: document has no viewable geometry'),
          )
          return
        }
        viewer
          .loadDocumentNode(doc, geometry)
          .then((model) => {
            // Cancelled while this request was in flight: the cleanup below
            // has already run and never saw this model, so unload it here or
            // it stays in the viewer next to the model that replaced it.
            if (cancelled) {
              unloadModel(viewer, model)
              return
            }
            loadedModel = model
            callbacksRef.current.onModelLoaded?.(model, doc)
          })
          .catch((error: Error) => {
            if (!cancelled) callbacksRef.current.onError?.(error)
          })
      },
      (code, message) => {
        if (cancelled) return
        callbacksRef.current.onError?.(
          new Error(`cantera aps-viewer: Document.load failed (${code}): ${message}`),
        )
      },
    )

    return () => {
      cancelled = true
      unloadModel(viewer, loadedModel)
      store.resetModel()
    }
  }, [status, urn, store, viewerEpoch])

  return (
    <APSViewerContext.Provider value={store}>
      <div
        className={className}
        style={{
          position: 'relative',
          ...(frameRadius === undefined
            ? {}
            : { borderRadius: frameRadius, overflow: 'hidden' as const }),
          ...style,
        }}
        data-aps-viewer=""
        data-aps-viewer-status={status}
        data-aps-viewer-radius={frameRadius}
      >
        <div ref={containerRef} style={{ position: 'absolute', inset: 0 }} />
        {children}
      </div>
    </APSViewerContext.Provider>
  )
}

'use client'

import { createContext, useContext } from 'react'
import type { ViewerStore } from '@/components/ui/aps-viewer/store'

export const APSViewerContext = createContext<ViewerStore | null>(null)

export function useAPSViewerStore(): ViewerStore {
  const store = useContext(APSViewerContext)
  if (!store) {
    throw new Error(
      'cantera aps-viewer: hooks must be used inside <APSViewer> (as children) ' +
        'or under an <APSViewerContext.Provider>.',
    )
  }
  return store
}

'use client'

import { useEffect, useMemo, useRef, useState, useSyncExternalStore } from 'react'
import { useAPSViewerStore } from '@/components/ui/aps-viewer/context'
import { ViewerStore } from '@/components/ui/aps-viewer/store'
import type {
  APSCameraState,
  APSExtensionStatus,
  APSPropertyResult,
  APSViewer3D,
  Vec3,
} from '@/lib/viewer-types'

/**
 * The live viewer instance (or null until ready). Re-renders when the viewer
 * mounts, attaches, or is torn down.
 */
export function useAPSViewer(): { viewer: APSViewer3D | null; isReady: boolean } {
  const store = useAPSViewerStore()
  const viewer = useSyncExternalStore(store.subscribe, store.getViewer, ViewerStore.getServerViewer)
  return { viewer, isReady: viewer !== null }
}

/** True once the current model's geometry has streamed in. */
export function useAPSModelLoaded(): boolean {
  const store = useAPSViewerStore()
  return useSyncExternalStore(
    store.subscribe,
    store.isModelLoaded,
    ViewerStore.getServerModelLoaded,
  )
}

export interface APSSelection {
  /** Currently selected dbIds (stable reference between selection events) */
  dbIds: readonly number[]
  select: (dbIds: number[] | number) => void
  clear: () => void
  isolate: (dbIds?: number[] | number) => void
  fitToView: (dbIds?: number[]) => void
}

/** Event-driven selection state plus the common selection verbs. */
export function useAPSSelection(): APSSelection {
  const store = useAPSViewerStore()
  const dbIds = useSyncExternalStore(
    store.subscribe,
    store.getSelection,
    ViewerStore.getServerSelection,
  )

  // The verbs memoize on the store alone, never on the selection snapshot, so
  // their identities survive selection events — safe in consumer dep arrays.
  const verbs = useMemo(
    () => ({
      select: (ids: number[] | number) => store.getViewer()?.select(ids),
      clear: () => store.getViewer()?.clearSelection(),
      isolate: (ids?: number[] | number) => store.getViewer()?.isolate(ids),
      fitToView: (ids?: number[]) => store.getViewer()?.fitToView(ids ?? null),
    }),
    [store],
  )

  return useMemo(() => ({ dbIds, ...verbs }), [dbIds, verbs])
}

export interface APSCamera {
  /** rAF-coalesced camera state (null until the first frame after load) */
  camera: APSCameraState | null
  setView: (position: Vec3, target: Vec3, up?: Vec3) => void
  fitToView: () => void
}

/** Camera state, updated at most once per animation frame while orbiting. */
export function useAPSCamera(): APSCamera {
  const store = useAPSViewerStore()
  const camera = useSyncExternalStore(store.subscribe, store.getCamera, ViewerStore.getServerCamera)

  // The verbs memoize on the store alone, never on the per-frame camera
  // snapshot: an orbit updates `camera` every animation frame, and verbs keyed
  // on it would re-run any consumer effect that lists them 60 times a second.
  const verbs = useMemo(
    () => ({
      setView: (position: Vec3, target: Vec3, up?: Vec3) => {
        const viewer = store.getViewer()
        if (!viewer) return
        // LMV accepts plain {x, y, z} vectors at runtime; the official typings
        // ask for THREE.Vector3, which is structurally a superset of Vec3.
        viewer.navigation.setView(position as THREE.Vector3, target as THREE.Vector3)
        if (up) viewer.navigation.setCameraUpVector(up as THREE.Vector3)
      },
      fitToView: () => store.getViewer()?.fitToView(null),
    }),
    [store],
  )

  return useMemo(() => ({ camera, ...verbs }), [camera, verbs])
}

/**
 * Subscribes a handler to any raw viewer event (e.g.
 * `Autodesk.Viewing.OBJECT_TREE_CREATED_EVENT`) with automatic cleanup.
 * The handler is kept in a ref, so inline closures are fine. Type the payload
 * through the type parameter: `useAPSViewerEvent<{ dbIdArray: number[] }>(...)`.
 */
export function useAPSViewerEvent<EventType = unknown>(
  eventType: string,
  handler: (event: EventType) => void,
): void {
  const { viewer } = useAPSViewer()
  const handlerRef = useRef(handler)
  // Synced after commit, not during render: a render React discards (Strict
  // Mode, a concurrent restart) must never leave its handler behind.
  useEffect(() => {
    handlerRef.current = handler
  })

  useEffect(() => {
    if (!viewer) return
    const listener = (event: EventType) => handlerRef.current(event)
    viewer.addEventListener(eventType, listener)
    return () => viewer.removeEventListener(eventType, listener)
  }, [viewer, eventType])
}

export interface APSPropertiesResult {
  data: APSPropertyResult[]
  isLoading: boolean
  error: Error | null
}

const EMPTY_PROPERTIES: APSPropertiesResult = Object.freeze({
  data: [],
  isLoading: false,
  error: null,
})

/**
 * Async property fetch for a set of dbIds. Pass `useAPSSelection().dbIds`
 * to get live properties-of-selection. Results are keyed by the request they
 * answer, so stale responses never overwrite fresh ones — and `key` is the
 * serialized identity of dbIds, so a consumer passing a freshly-computed
 * array every render does not refetch. While a fetch is in flight the
 * previous results stay visible with `isLoading: true`.
 */
export function useAPSProperties(dbIds: readonly number[]): APSPropertiesResult {
  const { viewer } = useAPSViewer()
  const key = dbIds.join(',')
  // Written only from async callbacks; the reset and loading states derive
  // during render by comparing against the last settled request.
  const [settled, setSettled] = useState<{
    viewer: APSViewer3D
    key: string
    data: APSPropertyResult[]
    error: Error | null
  } | null>(null)

  useEffect(() => {
    if (!viewer || key === '') return
    let cancelled = false

    Promise.all(
      key.split(',').map(
        (dbId) =>
          new Promise<APSPropertyResult>((resolve, reject) =>
            viewer.getProperties(
              Number(dbId),
              // The official typings mark name/externalId optional; LMV
              // populates both for every real dbId.
              (result) => resolve(result as APSPropertyResult),
              reject,
            ),
          ),
      ),
    )
      .then((data) => {
        if (!cancelled) setSettled({ viewer, key, data, error: null })
      })
      .catch((error) => {
        if (!cancelled)
          setSettled({
            viewer,
            key,
            data: [],
            error: error instanceof Error ? error : new Error(String(error)),
          })
      })

    return () => {
      cancelled = true
    }
  }, [viewer, key])

  return useMemo(() => {
    if (!viewer || key === '') return EMPTY_PROPERTIES
    if (settled && settled.viewer === viewer && settled.key === key) {
      return { data: settled.data, isLoading: false, error: settled.error }
    }
    // In flight: keep what last settled so lists do not blank out — but only
    // from the same viewer instance. A recreated viewer may hold a different
    // model, and its predecessor's properties must never pose as this
    // request's data.
    return {
      data: settled && settled.viewer === viewer ? settled.data : [],
      isLoading: true,
      error: null,
    }
  }, [viewer, key, settled])
}

let contextMenuCallbackId = 0

export type BuildContextMenu = (
  items: import('@/lib/viewer-types').APSContextMenuItem[],
  status: import('@/lib/viewer-types').APSContextMenuStatus,
) => import('@/lib/viewer-types').APSContextMenuItem[]

/**
 * Customizes the viewer's right-click menu. The builder receives the SDK's
 * default items and the menu status (what's under the cursor) and returns
 * the items to show — add, remove, or replace freely. Unregisters on unmount.
 */
export function useAPSContextMenu(build: BuildContextMenu): void {
  const { viewer } = useAPSViewer()
  const buildRef = useRef(build)
  // Synced after commit, not during render — see useAPSViewerEvent.
  useEffect(() => {
    buildRef.current = build
  })

  useEffect(() => {
    if (!viewer) return
    const id = `cantera-aps-viewer-menu-${++contextMenuCallbackId}`
    viewer.registerContextMenuCallback(id, (menu, status) => {
      const next = buildRef.current(menu.slice(), status)
      menu.length = 0
      menu.push(...next)
    })
    return () => {
      viewer.unregisterContextMenuCallback(id)
    }
  }, [viewer])
}

/**
 * Load lifecycle of every extension requested through the `extensions` prop,
 * keyed by id. Extensions load over the network, so a UI that offers an
 * extension's feature should wait for `'ready'` — and an `'error'` entry
 * means that feature is unavailable, not that the viewer is broken.
 */
export function useAPSExtensions(): Readonly<Record<string, APSExtensionStatus>> {
  const store = useAPSViewerStore()
  return useSyncExternalStore(
    store.subscribe,
    store.getExtensionStatuses,
    ViewerStore.getServerExtensionStatuses,
  )
}

export interface APSExtensionResult {
  status: 'idle' | APSExtensionStatus
  /** The loaded extension instance (null until ready). Cast to your extension's type. */
  extension: unknown
  error: Error | null
}

const IDLE_EXTENSION: APSExtensionResult = Object.freeze({
  status: 'idle',
  extension: null,
  error: null,
})

/**
 * Shallow equality over option bags. Options may hold SDK objects, circular
 * structures, or functions — never serialize them; compare by key identity.
 */
function sameOptions(a?: Record<string, unknown>, b?: Record<string, unknown>): boolean {
  if (a === b) return true
  if (!a || !b) return false
  const keys = Object.keys(a)
  if (keys.length !== Object.keys(b).length) return false
  return keys.every((key) => Object.is(a[key], b[key]))
}

/**
 * Loads a viewer extension for this component's lifetime and unloads it on
 * unmount. Returns the load status and the instance, so UI can gate on
 * readiness instead of assuming the network fetch succeeded.
 *
 * Changing `options` after load re-applies them through the extension's own
 * `setOptions` when it exposes one; extensions without `setOptions` keep
 * their load-time options (reload by changing `id` — i.e. remount). Changes
 * are detected by shallow comparison, so keep option values referentially
 * stable — an object or function literal recreated every render re-applies
 * every render.
 */
export function useAPSExtension(id: string, options?: Record<string, unknown>): APSExtensionResult {
  const { viewer } = useAPSViewer()
  // Written only from async callbacks; `idle` (no viewer) and `loading`
  // derive during render by comparing against the last settled load.
  const [settled, setSettled] = useState<{
    viewer: APSViewer3D
    id: string
    status: 'ready' | 'error'
    extension: unknown
    error: Error | null
  } | null>(null)
  const optionsRef = useRef(options)
  const appliedOptionsRef = useRef(options)
  // Synced after commit, not during render — see useAPSViewerEvent. Declared
  // before the load effect so a same-commit id change reads current options.
  useEffect(() => {
    optionsRef.current = options
  })

  useEffect(() => {
    if (!viewer) return
    let cancelled = false
    appliedOptionsRef.current = optionsRef.current
    viewer
      .loadExtension(id, optionsRef.current)
      .then((extension) => {
        if (cancelled) return
        setSettled({
          viewer,
          id,
          status: 'ready',
          extension: extension ?? viewer.getExtension(id),
          error: null,
        })
      })
      .catch((error) => {
        if (cancelled) return
        console.error(`cantera aps-viewer: failed to load extension "${id}"`, error)
        setSettled({
          viewer,
          id,
          status: 'error',
          extension: null,
          error: error instanceof Error ? error : new Error(String(error)),
        })
      })
    return () => {
      cancelled = true
      try {
        viewer.unloadExtension(id)
      } catch {
        // viewer may already be finished
      }
    }
  }, [viewer, id])

  const result = useMemo<APSExtensionResult>(() => {
    if (!viewer) return IDLE_EXTENSION
    if (settled && settled.viewer === viewer && settled.id === id) {
      return { status: settled.status, extension: settled.extension, error: settled.error }
    }
    return { status: 'loading', extension: null, error: null }
  }, [viewer, id, settled])

  const { status, extension } = result
  // Keyed on the fields it reads, not the whole result object, so an
  // unrelated change (a new error) cannot re-run the option pass.
  useEffect(() => {
    if (status !== 'ready' || sameOptions(appliedOptionsRef.current, options)) return
    appliedOptionsRef.current = options
    const loaded = extension as {
      setOptions?: (options: Record<string, unknown>) => unknown
    } | null
    loaded?.setOptions?.(options ?? {})
  }, [status, extension, options])

  return result
}

/** Convenience: viewer resize bound to a ResizeObserver on its container. */
export function useAPSAutoResize(): void {
  const { viewer } = useAPSViewer()
  useEffect(() => {
    if (!viewer || typeof ResizeObserver === 'undefined') return
    const observer = new ResizeObserver(() => viewer.resize())
    observer.observe(viewer.container)
    return () => observer.disconnect()
  }, [viewer])
}

import type { AutodeskGlobal, GetAccessToken } from '@/lib/viewer-types'

const VIEWER_HOST = 'https://developer.api.autodesk.com/modelderivative/v2/viewers'

export interface ViewerRuntimeOptions {
  getAccessToken: GetAccessToken
  /** SDK version, e.g. '7.*' (default) pins to latest v7 */
  version?: string
  /** Initializer environment (default 'AutodeskProduction2' — SVF2) */
  env?: string
  /** Initializer API (default 'streamingV2' — SVF2) */
  api?: string
  language?: string
}

let scriptPromise: Promise<AutodeskGlobal> | null = null
let runtimePromise: Promise<AutodeskGlobal> | null = null
let activeConsumers = 0
const tokenErrorListeners = new Set<(error: Error) => void>()

/**
 * Subscribes to token-supplier failures. The SDK's `getAccessToken` callback
 * has no rejection path — a backend that is down or a grant that expired would
 * otherwise leave the SDK waiting forever with nothing to report — so the
 * failure is broadcast here and `<APSViewer>` turns it into `onError`.
 * Returns an unsubscribe function.
 */
export function onViewerTokenError(listener: (error: Error) => void): () => void {
  tokenErrorListeners.add(listener)
  return () => {
    tokenErrorListeners.delete(listener)
  }
}

function reportTokenError(cause: unknown): void {
  const error = new Error('cantera aps-viewer: getAccessToken failed', { cause })
  if (tokenErrorListeners.size === 0) {
    // Nobody is listening: still fail loudly rather than silently.
    console.error(error, cause)
    return
  }
  for (const listener of tokenErrorListeners) listener(error)
}

function assertBrowser(): void {
  if (typeof window === 'undefined') {
    throw new Error(
      'cantera aps-viewer: the APS Viewer runtime can only load in the browser. ' +
        'Render <APSViewer> inside a client component; it is SSR-safe as long as ' +
        'you do not call loader functions during server rendering.',
    )
  }
}

/**
 * Injects the viewer <script> and <link> tags exactly once, no matter how
 * many components ask for them, and resolves when `window.Autodesk.Viewing`
 * exists. Safe to call repeatedly; concurrent callers share one promise.
 */
export function loadViewerScript(version = '7.*'): Promise<AutodeskGlobal> {
  assertBrowser()
  if (window.Autodesk?.Viewing) return Promise.resolve(window.Autodesk)
  if (scriptPromise) return scriptPromise

  scriptPromise = new Promise<AutodeskGlobal>((resolve, reject) => {
    const css = document.createElement('link')
    css.rel = 'stylesheet'
    css.href = `${VIEWER_HOST}/${version}/style.min.css`
    css.setAttribute('data-aps-viewer', 'style')
    document.head.appendChild(css)

    const script = document.createElement('script')
    script.src = `${VIEWER_HOST}/${version}/viewer3D.min.js`
    script.async = true
    script.setAttribute('data-aps-viewer', 'script')
    script.onload = () => {
      if (window.Autodesk?.Viewing) {
        resolve(window.Autodesk)
      } else {
        scriptPromise = null
        script.remove()
        css.remove()
        reject(
          new Error('cantera aps-viewer: viewer3D.min.js loaded but window.Autodesk is missing'),
        )
      }
    }
    script.onerror = () => {
      scriptPromise = null
      script.remove()
      css.remove()
      reject(
        new Error('cantera aps-viewer: failed to load the APS Viewer script from the Autodesk CDN'),
      )
    }
    document.head.appendChild(script)
  })

  return scriptPromise
}

/**
 * Loads the script (if needed) and runs `Autodesk.Viewing.Initializer` exactly
 * once. The Initializer is global in the SDK, so the first caller's options
 * win; subsequent calls share the initialized runtime.
 *
 * Call `releaseViewerRuntime()` when a consumer unmounts. The runtime itself
 * stays warm by default (re-initializing is expensive); pass
 * `shutdown: true` to tear it down when the last consumer releases.
 */
export function acquireViewerRuntime(options: ViewerRuntimeOptions): Promise<AutodeskGlobal> {
  assertBrowser()
  activeConsumers += 1
  if (runtimePromise) return runtimePromise

  const {
    getAccessToken,
    version = '7.*',
    env = 'AutodeskProduction2',
    api = 'streamingV2',
    language,
  } = options

  runtimePromise = loadViewerScript(version).then(
    (autodesk) =>
      new Promise<AutodeskGlobal>((resolve) => {
        autodesk.Viewing.Initializer(
          {
            env,
            api,
            language,
            getAccessToken: (onTokenReady?: (token: string, expiresInSeconds: number) => void) => {
              getAccessToken()
                .then(({ accessToken, expiresInSeconds }) =>
                  onTokenReady?.(accessToken, expiresInSeconds),
                )
                .catch(reportTokenError)
            },
          },
          () => resolve(autodesk),
        )
      }),
  )
  runtimePromise.catch(() => {
    runtimePromise = null
  })
  return runtimePromise
}

export function releaseViewerRuntime({ shutdown = false }: { shutdown?: boolean } = {}): void {
  activeConsumers = Math.max(0, activeConsumers - 1)
  if (
    shutdown &&
    activeConsumers === 0 &&
    typeof window !== 'undefined' &&
    window.Autodesk?.Viewing
  ) {
    window.Autodesk.Viewing.shutdown()
    runtimePromise = null
  }
}

/** Test-only: reset module state between test cases. */
export function __resetLoaderStateForTests(): void {
  scriptPromise = null
  runtimePromise = null
  activeConsumers = 0
  tokenErrorListeners.clear()
}

/** Normalizes a Model Derivative URN into the `urn:` documentId form. */
export function toDocumentId(urn: string): string {
  const trimmed = urn.trim()
  return trimmed.startsWith('urn:') ? trimmed : `urn:${trimmed}`
}

import type {
  APSCameraState,
  APSExtensionStatus,
  APSViewer3D,
  APSViewerStatus,
} from '@/lib/viewer-types'

type Listener = () => void

const EMPTY_SELECTION: readonly number[] = Object.freeze([])
const EMPTY_EXTENSIONS: Readonly<Record<string, APSExtensionStatus>> = Object.freeze({})

/**
 * Bridges the viewer's imperative event bus into a React 18/19 external
 * store. Snapshots are cached and replaced only when the underlying event
 * fires, so `useSyncExternalStore` gets referentially stable values and
 * never tears or loops.
 *
 * Camera changes fire once per animation frame during orbits, so camera
 * snapshots are coalesced through requestAnimationFrame.
 */
export class ViewerStore {
  private viewer: APSViewer3D | null = null
  private listeners = new Set<Listener>()
  private handlers: Array<[string, () => void]> = []
  private selection: readonly number[] = EMPTY_SELECTION
  private camera: APSCameraState | null = null
  private modelLoaded = false
  private rafId: number | null = null
  private extensions: Readonly<Record<string, APSExtensionStatus>> = EMPTY_EXTENSIONS
  private status: APSViewerStatus = 'idle'

  attach(viewer: APSViewer3D): void {
    const viewing = window.Autodesk?.Viewing
    if (!viewing) throw new Error('cantera aps-viewer: viewer runtime not loaded')
    this.viewer = viewer

    const on = (type: string, handler: () => void) => {
      viewer.addEventListener(type, handler)
      this.handlers.push([type, handler])
    }

    on(viewing.SELECTION_CHANGED_EVENT, () => {
      this.selection = Object.freeze(viewer.getSelection().slice())
      this.emit()
    })
    on(viewing.CAMERA_CHANGE_EVENT, () => this.scheduleCameraSnapshot())
    on(viewing.GEOMETRY_LOADED_EVENT, () => {
      this.modelLoaded = true
      // First camera snapshot once geometry exists, so useAPSCamera has an
      // initial value without waiting for the user to move the camera.
      this.scheduleCameraSnapshot()
      this.emit()
    })

    this.emit()
  }

  /**
   * Drops the model-loaded snapshot without tearing the viewer down. A URN
   * swap reuses the same store, so the flag has to fall back to false while
   * the next document loads — otherwise overlays keyed off
   * `useAPSModelLoaded()` disappear before there is anything to look at.
   */
  resetModel(): void {
    if (!this.modelLoaded) return
    this.modelLoaded = false
    this.emit()
  }

  /**
   * Viewer lifecycle status. Owned by the store — the viewer is an external
   * imperative resource, so its lifecycle is external state, written by
   * `<APSViewer>` as it acquires and releases the runtime.
   */
  setStatus(status: APSViewerStatus): void {
    if (this.status === status) return
    this.status = status
    this.emit()
  }

  /**
   * Load lifecycle of the extensions the viewer component was asked to load,
   * as a frozen snapshot keyed by extension id — replaced, never mutated, so
   * `useSyncExternalStore` sees each transition.
   */
  setExtensionStatus(id: string, status: APSExtensionStatus): void {
    if (this.extensions[id] === status) return
    this.extensions = Object.freeze({ ...this.extensions, [id]: status })
    this.emit()
  }

  detach(): void {
    if (this.viewer) {
      for (const [type, handler] of this.handlers) {
        this.viewer.removeEventListener(type, handler)
      }
    }
    this.handlers = []
    if (this.rafId !== null && typeof cancelAnimationFrame === 'function') {
      cancelAnimationFrame(this.rafId)
      this.rafId = null
    }
    this.viewer = null
    this.selection = EMPTY_SELECTION
    this.camera = null
    this.modelLoaded = false
    this.extensions = EMPTY_EXTENSIONS
    this.status = 'idle'
    this.emit()
  }

  subscribe = (listener: Listener): (() => void) => {
    this.listeners.add(listener)
    return () => {
      this.listeners.delete(listener)
    }
  }

  getViewer = (): APSViewer3D | null => this.viewer
  getSelection = (): readonly number[] => this.selection
  getCamera = (): APSCameraState | null => this.camera
  isModelLoaded = (): boolean => this.modelLoaded
  getExtensionStatuses = (): Readonly<Record<string, APSExtensionStatus>> => this.extensions
  getStatus = (): APSViewerStatus => this.status

  /** Server snapshots for useSyncExternalStore — stable, empty values. */
  static getServerViewer = (): APSViewer3D | null => null
  static getServerSelection = (): readonly number[] => EMPTY_SELECTION
  static getServerCamera = (): APSCameraState | null => null
  static getServerModelLoaded = (): boolean => false
  static getServerExtensionStatuses = (): Readonly<Record<string, APSExtensionStatus>> =>
    EMPTY_EXTENSIONS
  static getServerStatus = (): APSViewerStatus => 'idle'

  private emit(): void {
    for (const listener of this.listeners) listener()
  }

  private scheduleCameraSnapshot(): void {
    if (this.rafId !== null) return
    this.rafId = requestAnimationFrame(() => {
      this.rafId = null
      const viewer = this.viewer
      if (!viewer) return
      const nav = viewer.navigation
      this.camera = {
        position: { ...nav.getPosition() },
        target: { ...nav.getTarget() },
        up: { ...nav.getCameraUpVector() },
        isPerspective: nav.getCamera().isPerspective,
      }
      this.emit()
    })
  }
}

